pub async fn member_by_phone(c: &mut AsyncPgConnection, phone: &str) -> Result<Option<Value>> {
    Ok(
        sql_query("SELECT data FROM roster_members WHERE data->>'phone'=$1")
            .bind::<Text, _>(phone)
            .load::<Document>(c)
            .await?
            .pop()
            .map(|r| r.data),
    )
}
pub async fn member_conflicts(c: &mut AsyncPgConnection, v: &Value) -> Result<Vec<Value>> {
    Ok(sql_query("SELECT data FROM roster_members WHERE id<>$1 AND (data->>'phone'=$2 OR ($3<>'' AND data->>'memberId'=$3))").bind::<Text,_>(v["id"].as_str().unwrap_or("")).bind::<Text,_>(v["phone"].as_str().unwrap_or("")).bind::<Text,_>(v["memberId"].as_str().unwrap_or("")).load::<Document>(c).await?.into_iter().map(|r|r.data).collect())
}
pub async fn member_assignments(c: &mut AsyncPgConnection, id: &str) -> Result<Vec<Value>> {
    Ok(sql_query("SELECT a.data - '_isSpot' || jsonb_build_object('zoneName',z.data->>'name','positionName',p.data->>'name','duty',p.data->>'duty','spot',p.data->'spot','eventCode',e.data->>'code','eventName',e.data->>'name','eventDate',e.data->>'date') AS data FROM roster_assignments a JOIN roster_zones z ON z.id=a.zone_id JOIN roster_positions p ON p.id=a.position_id JOIN roster_events e ON e.id=a.event_id WHERE a.member_id=$1 ORDER BY e.data->>'date', e.data->>'session'").bind::<Text,_>(id).load::<Document>(c).await?.into_iter().map(|r|r.data).collect())
}
/// Filtering, enrichment, stable sorting, and pagination happen in PostgreSQL.
pub async fn page_members(
    c: &mut AsyncPgConnection,
    q: &crate::dto::roster::ListQuery,
) -> Result<Value> {
    let page = q.page.unwrap_or(1);
    let size = q.page_size.unwrap_or(25).min(200);
    if page == 0 || size == 0 {
        return Err(ApiError::bad("page and pageSize must be positive"));
    }
    let sort = match q.sort.as_deref().unwrap_or("name") {
        "name" => "lower(data->>'firstName') || ' ' || lower(data->>'lastName')",
        "phone" => "data->>'phone'",
        "unit" => "data->>'unit'",
        "joinedYear" => "(data->>'joinedYear')::int",
        "zone" => "data->'assignment'->>'zoneName'",
        _ => return Err(ApiError::bad("Invalid member sort")),
    };
    let dir = if q.dir.as_deref() == Some("desc") {
        "DESC"
    } else {
        "ASC"
    };
    let assignment = q.assignment.as_deref().unwrap_or("all");
    if !["all", "assigned", "unassigned"].contains(&assignment) {
        return Err(ApiError::bad(
            "assignment must be all, assigned or unassigned",
        ));
    }
    let query = format!(
        "WITH enriched AS (SELECT m.data || jsonb_build_object('assignment',(SELECT a.data - '_isSpot' || jsonb_build_object('zoneName',z.data->>'name','positionName',p.data->>'name') FROM roster_assignments a JOIN roster_zones z ON z.id=a.zone_id JOIN roster_positions p ON p.id=a.position_id WHERE a.member_id=m.id AND a.event_id=$7 AND a.data->>'status'<>'unavailable')) AS data FROM roster_members m), filtered AS (SELECT data FROM enriched WHERE ($1='' OR concat_ws(' ',data->>'firstName',data->>'lastName',data->>'phone',data->>'memberId') ILIKE '%' || $1 || '%') AND ($2='' OR data->>'status'=$2) AND ($3='' OR data->>'unit'=$3) AND ($4='' OR data->>'gender'=$4) AND ($5='' OR data->>'role'=$5) AND ($7='' OR $6='all' OR ($6='assigned' AND data->'assignment'<>'null'::jsonb) OR ($6='unassigned' AND data->'assignment'='null'::jsonb))) SELECT jsonb_build_object('items',COALESCE((SELECT jsonb_agg(data) FROM (SELECT data FROM filtered ORDER BY {sort} {dir} NULLS LAST,data->>'id' LIMIT $8::bigint OFFSET $9::bigint) page),'[]'::jsonb),'total',(SELECT count(*) FROM filtered),'page',$10::bigint,'pageSize',$8::bigint) AS data"
    );
    let data = sql_query(query)
        .bind::<Text, _>(q.q.as_deref().unwrap_or(""))
        .bind::<Text, _>(q.status.as_deref().unwrap_or(""))
        .bind::<Text, _>(q.unit.as_deref().unwrap_or(""))
        .bind::<Text, _>(q.gender.as_deref().unwrap_or(""))
        .bind::<Text, _>(q.role.as_deref().unwrap_or(""))
        .bind::<Text, _>(assignment)
        .bind::<Text, _>(q.event_id.as_deref().unwrap_or(""))
        .bind::<Text, _>(size.to_string())
        .bind::<Text, _>(page.saturating_sub(1).saturating_mul(size).to_string())
        .bind::<Text, _>(page.to_string())
        .get_result::<Document>(c)
        .await?
        .data;
    Ok(data)
}
